package com.atlasiq.governance;
import com.atlasiq.qir.*;import jakarta.enterprise.context.ApplicationScoped;import java.util.*;
@ApplicationScoped public class AdrQirLinker {public List<Link> link(List<ArchitectureDecisionRecord> adrs,QirModel m){List<Link> out=new ArrayList<>();for(var adr:adrs)for(String selector:adr.qirSelectors())for(QirNode n:m.nodes())if(matches(n,selector))out.add(new Link(adr.id(),n.id(),selector,adr.source()));return List.copyOf(out);}private boolean matches(QirNode n,String s){String[] p=s.split(":",2);return p.length==2&&(("type".equals(p[0])&&n.type().equals(p[1]))||("technology".equals(p[0])&&n.technology().equals(p[1]))||("id".equals(p[0])&&n.id().equals(p[1])));}public record Link(String adrId,String qirNodeId,String selector,String source){}}